import org.jf.dexlib2.iface.instruction.formats.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;import org.jf.dexlib2.immutable.reference.*;import org.jf.dexlib2.immutable.instruction.*;import org.jf.dexlib2.rewriter.*;import org.jf.dexlib2.writer.pool.DexPool;import java.io.*;import java.nio.file.*;import java.util.*;
/** Repairs only encoded int arrays passed to dex2jar decode_I, using exact original resource IDs. */
public class RebasePackedResourceArrays {
 public static void main(String[]a)throws Exception{Set<Integer> ids=new HashSet<>();for(String s:Files.readAllLines(Paths.get(a[1])))ids.add((int)Long.parseLong(s.replace("0x",""),16));var apk=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(28));Path out=Paths.get(a[2]);Files.createDirectories(out);int arrays=0,values=0,scalars=0,payloadValues=0;
 for(String name:apk.getDexEntryNames()){Map<String,String> replacements=new HashMap<>();for(ClassDef c:apk.getEntry(name).getDexFile().getClasses())for(Method m:c.getMethods()){if(m.getImplementation()==null)continue;Instruction previous=null;for(Instruction i:m.getImplementation().getInstructions()){
  if(i instanceof NarrowLiteralInstruction&&ids.contains(((NarrowLiteralInstruction)i).getNarrowLiteral()))scalars++;
  if(i instanceof ArrayPayload&&((ArrayPayload)i).getElementWidth()==4)for(Number n:((ArrayPayload)i).getArrayElements())if(ids.contains(n.intValue()))payloadValues++;
  if(i instanceof ReferenceInstruction&&((ReferenceInstruction)i).getReference() instanceof MethodReference){MethodReference r=(MethodReference)((ReferenceInstruction)i).getReference();if(r.getName().startsWith("$d2j$hex$")&&r.getName().endsWith("$decode_I")&&previous instanceof ReferenceInstruction&&((ReferenceInstruction)previous).getReference() instanceof StringReference){String s=((StringReference)((ReferenceInstruction)previous).getReference()).getString();if(!s.matches("[0-9a-fA-F]+")||s.length()%8!=0)throw new AssertionError("Invalid decoder input");StringBuilder b=new StringBuilder(s);int n=0;for(int k=0;k<s.length();k+=8){int v=0;for(int j=0;j<4;j++)v|=Integer.parseInt(s.substring(k+j*2,k+j*2+2),16)<<(j*8);if(ids.contains(v)){int mapped=(v&0xffffff)|0x80000000;StringBuilder h=new StringBuilder();for(int j=0;j<4;j++)h.append(String.format("%02x",(mapped>>>(j*8))&255));b.replace(k,k+8,h.toString());n++;}}if(n>0){replacements.put(s,b.toString());arrays++;values+=n;System.out.println("ARRAY "+name+" "+c.getType()+"."+m.getName()+" resource_ids="+n);}}}
 previous=i;}}
 final Map<String,String> map=replacements;DexRewriter rw=new DexRewriter(new RewriterModule(){public Rewriter<Instruction> getInstructionRewriter(Rewriters r){return new InstructionRewriter(r){public Instruction rewrite(Instruction i){if(i instanceof ReferenceInstruction&&((ReferenceInstruction)i).getReference() instanceof StringReference){String s=((StringReference)((ReferenceInstruction)i).getReference()).getString();if(map.containsKey(s)){if(i instanceof OneRegisterInstruction){int reg=((OneRegisterInstruction)i).getRegisterA();return i.getOpcode()==Opcode.CONST_STRING?new ImmutableInstruction21c(Opcode.CONST_STRING,reg,new ImmutableStringReference(map.get(s))):new ImmutableInstruction31c(Opcode.CONST_STRING_JUMBO,reg,new ImmutableStringReference(map.get(s)));}}}return super.rewrite(i);}};}});DexPool.writeTo(out.resolve(name).toString(),rw.getDexFileRewriter().rewrite(apk.getEntry(name).getDexFile()));}
 System.out.println("PACKED_ARRAYS="+arrays+" REBASED_IDS="+values+" REMAINING_SCALAR_ORIGINAL_IDS="+scalars+" ARRAY_PAYLOAD_ORIGINAL_IDS="+payloadValues);if(scalars>0||payloadValues>0)throw new AssertionError("Unresolved original literal resource IDs");
 }
}
